package dflow

import (
	"context"

	"github.com/k0923/go/lease"
)

// Wakeup persists a callback and its wake notification. token is generated by
// the engine and delivered with the Request notification; it is not a name
// chosen by node code. The caller/dispatcher subsequently invokes ResumeNode.
func (e *Engine) Wakeup(ctx context.Context, nodeID, token string, response any) (bool, error) {
	if nodeID == "" || token == "" {
		return false, ErrWaitNotFound
	}
	accepted, err := e.infra.Resolve(ctx, nodeID, token, response)
	if err != nil {
		return false, &InfrastructureError{Op: "Resolve", Cause: err}
	}
	return accepted, nil
}

// ResumeNode resolves an optional callback, then claims only the named node and
// advances its reachable successors. Without response, consume a persisted Wake.
// Nil can be delivered with one explicit nil argument. Old tokens are no-ops.
func (e *Engine) ResumeNode(ctx context.Context, nodeID, token string, response ...any) (state *State, err error) {
	if nodeID == "" || token == "" || len(response) > 1 {
		return nil, ErrWaitNotFound
	}
	if len(response) == 1 {
		if _, err := e.Wakeup(ctx, nodeID, token, response[0]); err != nil {
			return nil, err
		}
	}
	err = e.leases.Run(ctx, runLeaseKey, func(ctx context.Context, leaseToken lease.Token) error {
		state = &State{Nodes: map[string]NodeState{}}
		node, err := e.infra.GetNode(ctx, nodeID)
		if err != nil {
			return &InfrastructureError{"GetNode", err}
		}
		if node == nil {
			return ErrWaitNotFound
		}
		if node.Suspension == nil || node.Suspension.Token != token {
			return nil
		}
		task, err := e.infra.ClaimNode(ctx, leaseToken, nodeID)
		if err != nil {
			return &InfrastructureError{"ClaimNode", err}
		}
		if task == nil {
			return nil
		}
		return e.drive(ctx, leaseToken, state, task, true)
	})
	return state, err
}

// Drain recovers durable ready/interrupted work after process loss without
// reinitializing execution or reading original workflow input in advance.
func (e *Engine) Drain(ctx context.Context) (state *State, err error) {
	err = e.leases.Run(ctx, runLeaseKey, func(ctx context.Context, token lease.Token) error {
		state = &State{Nodes: map[string]NodeState{}}
		return e.drive(ctx, token, state, nil, false)
	})
	return state, err
}
